cat > /tmp/jwtcheck.test.ts <<'EOF'
import { createHmac } from "node:crypto";
import { expect, test } from "vitest";
import { verifyToken } from "/tmp/token-saver-runs/red-K1-jwt-deadline-3/src/auth/jwt.ts";
const b = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (h: object, p: object, s = "k") => { const d = `${b(h)}.${b(p)}`; return `${d}.${createHmac("sha256", s).update(d).digest("base64url")}`; };
const now = Math.floor(Date.now() / 1000);
test("x", () => {
  expect(verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp: now + 60 }), "k")).toEqual({ sub: "u1", exp: now + 60 });
  expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp: now - 1 }), "k")).toThrow("expired");
  expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp: now + 60 }), "wrong")).toThrow("signature");
  expect(() => verifyToken(`${b({ alg: "none" })}.${b({ sub: "u1", exp: now + 60 })}.`, "k")).toThrow("alg");
  expect(() => verifyToken("abc", "k")).toThrow("malformed");
});
EOF
npx vitest run --root / /tmp/jwtcheck.test.ts 2>&1 | tail -6; npx tsc --noEmit -p . 2>&1 | tail -5; rm /tmp/jwtcheck.test.ts

